#!/usr/bin/env bash
# Generated by testing/render-graders.sh from validate.sh. Do not edit by hand.
# Run by astrona test after the reference solution: wait, with a timeout,
# until the restarted kubelet and static Pods answer and every outcome passes.
# Runs on the lab VM as the astrona account (astrona pipes it into bash).

# >>> shared checks >>>
LAB_NAME=ats-032-lab-030-02-03
LAB_CONTEXT="kubernetes-admin@astro-$LAB_NAME"
NODE=controlplane
MANIFEST=/etc/kubernetes/manifests/kube-apiserver.yaml
STARFLEET=starfleet-032-030-02-03
OUTPOST=outpost-032-030-02-03
OUTCOMES="authorization-mode-secure impersonation-narrowed"

kube() {
  sudo -n kubectl --kubeconfig /etc/kubernetes/admin.conf --request-timeout=15s "$@" </dev/null
}

# Context guard: the graders only read this VM's own cluster.
lab_guard() {
  local context namespace
  if ! sudo -n test -r /etc/kubernetes/admin.conf; then
    echo "FAIL: guard: /etc/kubernetes/admin.conf is missing, so this is not the lab VM or kubeadm init did not run"
    return 1
  fi
  context=$(kube config current-context 2>/dev/null) || context=""
  if [ "$context" != "$LAB_CONTEXT" ]; then
    echo "FAIL: guard: admin.conf context is '$context', expected '$LAB_CONTEXT'"
    return 1
  fi
  for namespace in "$STARFLEET" "$OUTPOST"; do
    if ! kube -n "$namespace" get serviceaccount probe >/dev/null 2>&1; then
      echo "FAIL: guard: ServiceAccount probe in $namespace is not readable (is the API server running? keep the lab objects)"
      return 1
    fi
  done
}

# Sends a SubjectAccessReview and prints "<allowed> <reason>".
# Arguments: user, comma-separated groups, resourceAttributes as JSON.
review() {
  local body
  body=$(jq -n --arg user "$1" --arg groups "$2" --argjson attributes "$3" \
    '{apiVersion: "authorization.k8s.io/v1", kind: "SubjectAccessReview",
      spec: {user: $user, groups: ($groups | split(",")), resourceAttributes: $attributes}}')
  sudo -n kubectl --kubeconfig /etc/kubernetes/admin.conf --request-timeout=15s \
    create -o json -f - <<<"$body" 2>/dev/null \
    | jq -r '"\(.status.allowed // false) \(.status.reason // "")"'
}

# Prints the authorization modes of an argument list, one per line.
modes_of() {
  sed -n 's/^ *-* *--authorization-mode=//p' | head -n 1 | tr ',' '\n'
}

check_authorization_mode_secure() {
  local file_modes pod running_modes answer
  file_modes=$(sudo -n cat "$MANIFEST" | modes_of)
  if grep -qx AlwaysAllow <<<"$file_modes"; then
    echo "FAIL: authorization-mode-secure: $MANIFEST still lists AlwaysAllow in --authorization-mode"
    return 1
  fi
  if ! grep -qx Node <<<"$file_modes" || ! grep -qx RBAC <<<"$file_modes"; then
    echo "FAIL: authorization-mode-secure: $MANIFEST must list Node and RBAC in --authorization-mode"
    return 1
  fi
  pod=$(kube -n kube-system get pod "kube-apiserver-$NODE" -o json 2>/dev/null) || pod=""
  running_modes=$(jq -r '.spec.containers[0] | ((.command // []) + (.args // []))[]' <<<"$pod" 2>/dev/null | modes_of)
  if grep -qx AlwaysAllow <<<"$running_modes" || ! grep -qx Node <<<"$running_modes" \
    || ! grep -qx RBAC <<<"$running_modes"; then
    echo "FAIL: authorization-mode-secure: the running kube-apiserver must use Node and RBAC without AlwaysAllow (wait for the restart)"
    return 1
  fi
  answer=$(review nobody system:authenticated '{"verb":"list","resource":"secrets","namespace":"kube-system"}')
  if [ "${answer%% *}" != "false" ]; then
    echo "FAIL: authorization-mode-secure: a user without RBAC rules can still list Secrets in kube-system"
    return 1
  fi
  echo "PASS: authorization-mode-secure: the kube-apiserver runs with Node,RBAC and a user without RBAC rules cannot list Secrets"
}

check_impersonation_narrowed() {
  local groups=helpdesk,system:authenticated answer label attributes
  answer=$(review helpdesk-user "$groups" \
    "{\"verb\":\"impersonate\",\"resource\":\"serviceaccounts\",\"name\":\"probe\",\"namespace\":\"$STARFLEET\"}")
  if [ "${answer%% *}" != "true" ] || [[ "${answer#* }" != RBAC:* ]]; then
    echo "FAIL: impersonation-narrowed: the group helpdesk must keep an RBAC rule to impersonate the ServiceAccount probe in $STARFLEET"
    return 1
  fi
  while IFS='|' read -r label attributes; do
    answer=$(review helpdesk-user "$groups" "$attributes")
    if [ "${answer%% *}" != "false" ]; then
      echo "FAIL: impersonation-narrowed: the group helpdesk can still impersonate $label"
      return 1
    fi
  done <<EOF
the ServiceAccount probe in $OUTPOST|{"verb":"impersonate","resource":"serviceaccounts","name":"probe","namespace":"$OUTPOST"}
the ServiceAccount default in $STARFLEET|{"verb":"impersonate","resource":"serviceaccounts","name":"default","namespace":"$STARFLEET"}
the user kubernetes-admin|{"verb":"impersonate","resource":"users","name":"kubernetes-admin"}
the group system:masters|{"verb":"impersonate","resource":"groups","name":"system:masters"}
EOF
  echo "PASS: impersonation-narrowed: the group helpdesk can impersonate only the ServiceAccount probe in $STARFLEET"
}

grade() {
  lab_guard || return 1
  case "$1" in
    authorization-mode-secure) check_authorization_mode_secure ;;
    impersonation-narrowed) check_impersonation_narrowed ;;
    *) echo "FAIL: Unknown outcome '$1'"; return 1 ;;
  esac
}
# <<< shared checks <<<

main() {
  local attempt outcome output all_passed
  for attempt in $(seq 1 60); do
    all_passed=true
    output=""
    for outcome in $OUTCOMES; do
      output+="$(grade "$outcome")"'
' || all_passed=false
    done
    if $all_passed; then
      printf '%s' "$output"
      echo "PASS: the reference solution settled (attempt $attempt)"
      return 0
    fi
    sleep 5
  done
  printf '%s' "$output"
  echo "FAIL: the reference solution did not pass within five minutes"
  return 1
}

main
